sql_query:
SELECT "Is PD-L1 positivity inclusion criteria"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Is PD-L1 positivity inclusion criteria", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Name of ICI", '')) = 'Pembrolizumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Is PD-L1 positivity inclusion criteria" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Is PD-L1 positivity inclusion criteria", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Name of ICI", '')) = 'Pembrolizumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_pd_l1_required(source_value) AS "pd_l1_required"
FROM base;
